// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait IntentQualifier_supervisorProcess_intentQualifier_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier)
  }

  /** helper function to set the values of all input ports.
   * @param pilotIntent payload for data port pilotIntent
   */
  def put_concrete_inputs(pilotIntent : Docked_Service_Access_Lifecycle_Supervisor.PilotIntent.Type): Unit = {
    put_pilotIntent(pilotIntent)
  }


  /** helper function to check IntentQualifier_supervisorProcess_intentQualifier's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param qualifiedIntent method that will be called with the value of the outgoing data
   *        port 'qualifiedIntent'.
   */
  def check_concrete_output(qualifiedIntent: Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent.Type => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val qualifiedIntentValue: Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent.Type = get_qualifiedIntent().get
    if(!qualifiedIntent(qualifiedIntentValue)) {
      testFailures = testFailures :+ st"'qualifiedIntent' did not match expected: value of the outgoing data port is ${qualifiedIntentValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_pilotIntent(value : Docked_Service_Access_Lifecycle_Supervisor.PilotIntent.Type): Unit = {
    Art.insertInInfrastructurePort(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier.operational_api.pilotIntent_Id, Docked_Service_Access_Lifecycle_Supervisor.PilotIntent_Payload(value))
  }

  // getter for out DataPort
  def get_qualifiedIntent(): Option[Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent.Type] = {
    val value: Option[Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent.Type] = get_qualifiedIntent_payload() match {
      case Some(Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port qualifiedIntent.  Expecting 'Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent_Payload' but received ${v}")
      case _ => None[Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent.Type]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_qualifiedIntent_payload(): Option[Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.DockedServiceAccessLifecycleSupervisorSystem_Instance_supervisorProcess_intentQualifier.initialization_api.qualifiedIntent_Id).asInstanceOf[Option[Docked_Service_Access_Lifecycle_Supervisor.QualifiedIntent_Payload]]
  }

}
